routing {
    get("/users/{id}") {                                    // one handler per route
        val user = users.find(call.parameters["id"]!!.toLong())   // domain
        if (user == null) {
            call.respond(HttpStatusCode.NotFound)           // responder
        } else {
            call.respond(UserDto(user.id, user.name))       // responder
        }
    }
}
